    },
    REJECTED: {
      className: 'issue-status-badge--rejected',
      icon: <XCircle size={13} />,
      label: t('issueReview.rejected'),
    },
  };

  const current = config[status] || {
    className: 'issue-status-badge--rejected',
    icon: null,
    label: status || '—',
