          <p className="quality-wizard-subtitle">{t('grpo.manualProductDesc')}</p>
        </div>
        <div className="quality-form-grid qrev-meta-grid">
          {/* Item Group */}
          <label className="form-field quality-form-field--full">
            <span>{t('quality.itemGroup')} *</span>
