              {renderInfoItem(t('quality.selectWarehouse'), selectedWarehouse ? `${selectedWarehouse.code || selectedWarehouse.WarehouseCode} - ${selectedWarehouse.name || selectedWarehouse.WarehouseName}` : form.warehouse_code || '-')}
