            loading={costCentersLoading}
            onChange={(event) => updateField('location', event.target.value)}
            placeholder={costCentersLoading ? t('common.loading') : t('quality.selectLocationOptional')}
          >
            <option value="">{costCentersLoading ? t('common.loading') : t('quality.selectLocationOptional')}</option>
            {form.location && !costCentersDim1.some((cc) => cc.code === form.location) && (
              <option value={form.location}>{form.location}</option>
            )}
            {costCentersDim1.map((cc) => (
              <option key={cc.code} value={cc.code}>
                {cc.code} - {cc.name}
              </option>
            ))}
          </SearchableSelect>
          {costCenterError1 && (
            <span className="form-field__hint grpo-field-error">
              {t('quality.costCenterLoadFailed')}
              <button
                type="button"
                className="app-button app-button--secondary"
                onClick={() => reloadCostCenter(1)}
              >
                {t('common.retry')}
              </button>
            </span>
          )}
        </label>
        <label className="form-field">
          <span>{`${t('quality.general')} (${t('common.optional')})`}</span>
          <SearchableSelect
            className="app-input"
            value={form.general || ''}
            disabled={!canEdit || costCentersLoading}
            loading={costCentersLoading}
            onChange={(event) => updateField('general', event.target.value)}
            placeholder={costCentersLoading ? t('common.loading') : t('quality.selectGeneralOptional')}
          >
            <option value="">{costCentersLoading ? t('common.loading') : t('quality.selectGeneralOptional')}</option>
            {form.general && !costCentersDim2.some((cc) => cc.code === form.general) && (
              <option value={form.general}>{form.general}</option>
            )}
            {costCentersDim2.map((cc) => (
              <option key={cc.code} value={cc.code}>
                {cc.code} - {cc.name}
              </option>
            ))}
          </SearchableSelect>
          {costCenterError2 && (
            <span className="form-field__hint grpo-field-error">
              {t('quality.costCenterLoadFailed')}
              <button
                type="button"
                className="app-button app-button--secondary"
                onClick={() => reloadCostCenter(2)}
              >
                {t('common.retry')}
              </button>
            </span>
          )}
        </label>
      </div>
    );



    // Manual Intake flow: steps 0 to 7 (operational, batches, and review handled by common step index branches)
    if (isManual) {
      if (activeStep === 0) return renderManualVehicleStep();
      if (activeStep === 1) return renderManualSupplierStep();
      if (activeStep === 2) return renderManualProductStep();
      if (activeStep === 3) return renderManualWarehouseStep();
      if (activeStep === 4) {
        return (
          <section className="card-panel quality-wizard-card--wide grpo-draft-card">
            <div className="quality-wizard-heading">
              <h1 className="page-title">{t('quality.grpoSteps.manualItemWarehouse')}</h1>
              <p className="quality-wizard-subtitle">{t('quality.grpoItemDetailsDesc')}</p>
            </div>
            <div className="feedback-message feedback-message--info grpo-draft-card__notice">
              {t('grpo.manualIntakeNotice')}
            </div>

            {/* SECTION 1: بيانات الصنف والتسعير */}
            <div className="grpo-review-section" style={{ marginTop: '16px', marginBottom: '24px' }}>
              <h3 className="grpo-review-section__title">
                📦 {t('quality.grpoSteps.itemAndPricingSection')}
              </h3>
              {renderItemFields()}
            </div>

            {/* SECTION 2: المخزن والخلية التخزينية */}
            <div className="grpo-review-section" style={{ marginTop: '24px', borderTop: '1px solid var(--border)', paddingTop: '20px' }}>
              <h3 className="grpo-review-section__title">
                📍 {t('quality.grpoSteps.warehouseAndBinSection')}
              </h3>
              {renderWarehouseFields()}
            </div>

            {renderWizardNav()}
          </section>
        );
      }
      if (activeStep === 6) return renderManualReviewStep();
      if (activeStep === 7) return renderManualBatchStep();
    }

    // Standard / Quality / Weighbridge GRPO flow: 5 steps intact
    if (!isManual && activeStep === itemIndex) {
      return (
        <section className="card-panel quality-wizard-card--wide grpo-draft-card">
          <div className="quality-wizard-heading">
            <h1 className="page-title">{t('quality.grpoItemDetails')}</h1>
            <p className="quality-wizard-subtitle">{t('quality.grpoItemDetailsDesc')}</p>
          </div>
          {renderItemFields()}
          {renderWizardNav()}
        </section>
      );
    }

    if (!isManual && activeStep === warehouseIndex) {
      return (
        <section className="card-panel quality-wizard-card--wide grpo-draft-card">
          <div className="quality-wizard-heading">
            <h1 className="page-title">{t('quality.grpoSteps.warehouse')}</h1>
            <p className="quality-wizard-subtitle">{t('quality.warehouseBinDesc')}</p>
          </div>
          {renderWarehouseFields()}
          {renderWizardNav()}
        </section>
      );
    }

  const renderBatchDataStep = () => (
    <section className="card-panel quality-wizard-card--wide grpo-draft-card">
      <div className="quality-wizard-heading">
        <h1 className="page-title">{t('quality.batchDataTitle')}</h1>
        <p className="quality-wizard-subtitle">{t('quality.batchDataDesc')}</p>
      </div>

      {/* ── Balance Indicator Banner ── */}
      <div className={`batch-balance-banner ${isBalanced ? 'batch-balance-banner--success' : 'batch-balance-banner--warning'}`}>
        <div className="batch-balance-metrics">
          <div className="batch-balance-metric">
            <span className="batch-balance-label">{t('quality.totalRequiredQty')}</span>
            <strong className="batch-balance-val">
              {requiredQty} {form.uom_name || form.uom_code || draft?.uom_name || draft?.uom_code || 'KG'}
            </strong>
          </div>
          <div className="batch-balance-metric">
            <span className="batch-balance-label">{t('quality.allocatedQty')}</span>
            <strong className="batch-balance-val">
              {totalAllocated} {form.uom_name || form.uom_code || draft?.uom_name || draft?.uom_code || 'KG'}
            </strong>
          </div>
          <div className="batch-balance-metric">
            <span className="batch-balance-label">{t('quality.remainingBalance')}</span>
            <strong
              className="batch-balance-val"
              style={{ color: isBalanced ? 'var(--success, #2e7d32)' : 'var(--danger, #c62828)' }}
            >
              {remainingBalance} {form.uom_name || form.uom_code || draft?.uom_name || draft?.uom_code || 'KG'}
            </strong>
          </div>
        </div>
        <div className="batch-balance-status">
          {isBalanced ? (
            <span className="batch-balance-msg batch-balance-msg--ok">
              ✅ {t('quality.quantitiesBalanced')}
            </span>
          ) : (
            <span className="batch-balance-msg batch-balance-msg--err">
              ⚠️ {t('quality.quantityMismatch', Math.abs(remainingBalance).toFixed(3))}
            </span>
          )}
        </div>
      </div>

      {errors.batches_balance && (
        <div className="feedback-message feedback-message--error" style={{ marginBottom: '16px' }}>
          {errors.batches_balance}
        </div>
      )}

      {/* ── Batches List ── */}
      <div className="batch-list" style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        {batches.map((batch, index) => {
          const subStep = batchSubSteps[batch.id] ?? (isPosted ? 2 : 0);
          const isConfirmed = subStep >= 2;
          const attrIdx = batchAttrIdx[batch.id] ?? 0;
          const attrDef = ATTR_FIELDS[attrIdx] || ATTR_FIELDS[0];

          const rawAttrOpts = attrDef.text
            ? []
            : attrDef.key === 'company'
              ? companyOptions
              : attrDef.key === 'vendor'
                ? getBatchFieldOptions('vendor', batch.vendor, [
                    ...(form.vendor_name ? [{ value: form.vendor_name, label: form.vendor_name }] : []),
                    ...farms.map((f) => ({ value: f.name, label: `${f.code} - ${f.name}` })),
                  ])
                : getBatchFieldOptions(attrDef.key, batch[attrDef.stateKey]);

          const goToSubStep = (nextSub) => {
            setBatchSubSteps((s) => ({ ...s, [batch.id]: nextSub }));
          };

          const attrNext = () => {
            if (attrIdx < ATTR_FIELDS.length - 1) {
              setBatchAttrIdx((s) => ({ ...s, [batch.id]: attrIdx + 1 }));
            } else {
              setBatchAttrIdx((s) => ({ ...s, [batch.id]: 0 }));
              setBatchSubSteps((s) => ({ ...s, [batch.id]: 2 }));
            }
          };

          const attrPrev = () => {
            if (attrIdx > 0) {
              setBatchAttrIdx((s) => ({ ...s, [batch.id]: attrIdx - 1 }));
            } else {
              setBatchSubSteps((s) => ({ ...s, [batch.id]: 0 }));
            }
          };

          /* ── SUB-STEP 2: CONFIRMED COMPACT SUMMARY ── */
          if (isConfirmed) {
            return (
              <article key={batch.id} className="batch-card batch-card--confirmed">
                <div className="batch-card__header">
                  <div className="batch-card__title">
                    <span className="batch-card__index batch-card__index--success">
                      ✅ {t('quality.batchLabel', index + 1)}
                    </span>
                    <strong style={{ fontSize: '13px' }}>
                      🏷️ {batch.batch_number || t('quality.batchRequired')}
                    </strong>
                  </div>
                  {canEdit && (
                    <div className="batch-card__actions grpo-batch-card-actions">
                      <button
                        type="button"
                        className="app-button app-button--secondary batch-card__action-btn"
                        onClick={() => goToSubStep(0)}
                      >
                        {t('quality.editBatch')}
                      </button>
                      <button
                        type="button"
                        className="app-button app-button--secondary batch-card__action-btn"
                        onClick={() => handleDuplicateBatch(batch)}
                      >
                        {t('quality.duplicateBatch')}
                      </button>
                      {batches.length > 1 && (
                        <button
                          type="button"
                          className="app-button app-button--secondary batch-card__action-btn"
                          style={{ color: 'var(--danger)' }}
                          onClick={() => handleRemoveBatch(batch.id)}
                        >
                          {t('quality.removeBatch')}
                        </button>
                      )}
                    </div>
                  )}
                </div>

                <div className="details-grid details-grid--sm">
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.grpoQuantity')}</span>
                    <input
                      className="app-input"
                      type="number"
                      step="any"
                      min="0"
                      value={batch.quantity ?? 0}
                      readOnly={!canEdit}
                      onChange={(e) => handleBatchChange(batch.id, 'quantity', e.target.value)}
                    />
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.binLocation')}</span>
                    <div className="detail-item__value detail-item__value--sm">
                      {batch.bin_location_code || '-'}
                    </div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.manufacturingDate')}</span>
                    <div className="detail-item__value detail-item__value--sm">
                      {batch.manufacturing_date || '-'}
                    </div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.admissionDate')}</span>
                    <div className="detail-item__value detail-item__value--sm">
                      {batch.admission_date || '-'}
                    </div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.batchAttrs.vendor')}</span>
                    <div className="detail-item__value detail-item__value--sm">{batch.vendor || '-'}</div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.batchAttrs.part')}</span>
                    <div className="detail-item__value detail-item__value--sm">{batch.part || '-'}</div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.batchAttrs.company')}</span>
                    <div className="detail-item__value detail-item__value--sm">{batch.company || '-'}</div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.batchAttrs.season')}</span>
                    <div className="detail-item__value detail-item__value--sm">{batch.season || '-'}</div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.batchAttrs.batchAttribute1')}</span>
                    <div className="detail-item__value detail-item__value--sm">{batch.batch_attribute_1 || '-'}</div>
                  </div>
                  <div className="detail-item detail-item--sm">
                    <span className="detail-item__label detail-item__label--xs">{t('quality.batchAttrs.batchAttribute2')}</span>
                    <div className="detail-item__value detail-item__value--sm">{batch.batch_attribute_2 || '-'}</div>
                  </div>
                </div>
              </article>
            );
          }

          /* ── SUB-STEP 0 & 1: ACTIVE BATCH MINI-WIZARD ── */

          return (
            <article key={batch.id} className="batch-card batch-card--active">
              <div className="batch-card__header">
                <div className="batch-card__title">
                  <span className="batch-card__index">{t('quality.batchLabel', index + 1)}</span>
                  <strong style={{ fontSize: '13px' }}>
                    🏷️ {batch.batch_number || t('quality.batchRequired')}
                  </strong>
                </div>
                {batches.length > 1 && canEdit && (
                  <button
                    type="button"
                    className="icon-button icon-button--danger"
                    onClick={() => handleRemoveBatch(batch.id)}
                  >
                    ✕
                  </button>
                )}
              </div>

              {/* Sub-step indicator */}
              <div className="attr-stepper-scroll" style={{ marginBottom: '16px' }}>
                <div className="attr-stepper-row">
                  <button
                    type="button"
                    className="attr-stepper-btn"
                    data-attr-active={String(subStep === 0)}
                    onClick={() => goToSubStep(0)}
                  >
                    <div
                      className="attr-stepper-circle"
                      style={{
                        background: subStep > 0 ? 'var(--success)' : 'var(--primary)',
                        color: '#fff',
                      }}
                    >
                      {subStep > 0 ? '✓' : '1'}
                    </div>
                    <span className="attr-stepper-label">{t('quality.basicAndBin')}</span>
                  </button>
                  <div
                    className="attr-connector"
                    style={{ background: subStep > 0 ? 'var(--success)' : 'var(--border)' }}
                  />
                  <button
                    type="button"
                    className="attr-stepper-btn"
                    data-attr-active={String(subStep === 1)}
                    onClick={() => goToSubStep(1)}
                  >
                    <div
                      className="attr-stepper-circle"
                      style={{
                        background: subStep === 1 ? 'var(--primary)' : 'var(--bg-muted)',
                        color: subStep === 1 ? '#fff' : 'var(--text-subtle)',
                      }}
                    >
                      2
                    </div>
                    <span className="attr-stepper-label">{t('quality.batchProperties')}</span>
                  </button>
                </div>
              </div>

              {/* ── Sub-step 0: Basic & Bin ── */}
              {subStep === 0 && (
                <div className="wizard-bin-wrap">
                  <div className="quality-form-grid qrev-meta-grid" style={{ marginBottom: '16px' }}>
                    <label className="form-field">
                      <span>{t('quality.batchNumber')} *</span>
                      <input
                        className="app-input"
                        type="text"
                        value={batch.batch_number}
                        onChange={(e) => handleBatchChange(batch.id, 'batch_number', e.target.value)}
                        placeholder={t('quality.batchNumber')}
                      />
                    </label>
                    <label className="form-field">
                      <span>{t('quality.grpoQuantity')} *</span>
                      <input
                        className="app-input"
                        type="number"
                        step="any"
                        min="0"
                        value={batch.quantity}
                        onChange={(e) => handleBatchChange(batch.id, 'quantity', e.target.value)}
                      />
                    </label>
                    <label className="form-field">
                      <span>{t('quality.manufacturingDate')}</span>
                      <input
                        className="app-input"
                        type="date"
                        value={batch.manufacturing_date}
                        onChange={(e) => handleBatchChange(batch.id, 'manufacturing_date', e.target.value)}
                      />
                    </label>
                    <label className="form-field">
                      <span>{t('quality.admissionDate')}</span>
                      <input
                        className="app-input"
                        type="date"
                        value={batch.admission_date}
                        onChange={(e) => handleBatchChange(batch.id, 'admission_date', e.target.value)}
                      />
                    </label>
                    <label className="form-field">
                      <span>{t('quality.expiryDate')}</span>
                      <input
                        className="app-input"
                        type="date"
                        value={batch.expiry_date}
                        onChange={(e) => handleBatchChange(batch.id, 'expiry_date', e.target.value)}
                      />
                    </label>
                  </div>

                  <div className="grpo-assigned-bin-badge" style={{ marginTop: '8px', marginBottom: '16px', padding: '10px 14px', background: 'var(--bg-muted, #f8f9fa)', borderRadius: '6px', border: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '12px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <span style={{ fontSize: '1.2rem' }}>📍</span>
                      <div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--text-subtle)', textTransform: 'uppercase', fontWeight: 600 }}>{t('quality.binLocation')}</div>
                        <div style={{ fontWeight: 600, color: 'var(--text-main)' }}>
                          {batch.bin_location_code || form.bin_code || '-'}
                        </div>
                      </div>
                    </div>
                    {form.warehouse_code && (
                      <span className="rr-status-badge rr-status-badge--info" style={{ fontSize: '0.75rem' }}>
                        {form.warehouse_code}
                      </span>
                    )}
                  </div>

                  <div className="wizard-nav-row" style={{ marginTop: '16px' }}>
                    <button
                      type="button"
                      className="app-button app-button--primary app-button--block wizard-nav-btn--sm"
                      onClick={() => goToSubStep(1)}
                    >
                      {t('common.next')} ({t('quality.batchProperties')}) ➔
                    </button>
                  </div>
                </div>
              )}

              {/* ── Sub-step 1: Batch Properties (6 attributes) ── */}
              {subStep === 1 && (
                <div>
                  {batchAttributesLoading && (
                    <div className="feedback-message feedback-message--info" style={{ marginBottom: '14px' }}>
                      ⏳ {t('common.loading')}
                    </div>
                  )}

                  {/* Attr Stepper Row */}
                  <div className="attr-stepper-scroll">
                    <div className="attr-stepper-row">
                      {ATTR_FIELDS.map((field, i) => {
                        const isDone = i < attrIdx;
                        const isActive = i === attrIdx;
                        return (
                          <React.Fragment key={field.key}>
                            <button
                              type="button"
                              onClick={() => setBatchAttrIdx((s) => ({ ...s, [batch.id]: i }))}
                              className="attr-stepper-btn"
                              data-attr-active={String(isActive)}
                            >
                              <div
                                className="attr-stepper-circle"
                                style={{
                                  background: isDone ? 'var(--success)' : isActive ? 'var(--primary)' : 'var(--bg-muted)',
                                  color: isDone || isActive ? '#fff' : 'var(--text-subtle)',
                                  border: `1.5px solid ${isDone ? 'var(--success)' : isActive ? 'var(--primary)' : 'var(--border)'}`,
                                }}
                              >
                                {isDone ? '✓' : i + 1}
                              </div>
                              <span
                                className="attr-stepper-label"
                                style={{
                                  fontWeight: isActive ? 700 : 500,
                                  color: isDone ? 'var(--success)' : isActive ? 'var(--primary)' : 'var(--text-subtle)',
                                }}
                              >
                                {t(field.labelKey) || field.label}
                              </span>
                            </button>
                            {i < ATTR_FIELDS.length - 1 && (
                              <div
                                className="attr-connector"
                                style={{ background: i < attrIdx ? 'var(--success)' : 'var(--border)' }}
                              />
                            )}
                          </React.Fragment>
                        );
                      })}
                    </div>
                  </div>

                  {/* Current Attribute Header */}
                  <div style={{ margin: '14px 0 10px', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                    <strong>
                      {attrIdx + 1}. {t(attrDef.labelKey) || attrDef.label}
                    </strong>
                    {batch[attrDef.stateKey] && (
                      <span className="attr-selected-chip">✓ {batch[attrDef.stateKey]}</span>
                    )}
                  </div>

                  {/* Non-text attribute cards */}
                  {!attrDef.text && (() => {
                    const isBrand = attrDef.key === 'brand';
                    const isEmpty = !batch[attrDef.stateKey];
                    return (
                      <div
                        className="attr-options-grid"
                        style={{
                          gridTemplateColumns: `repeat(auto-fill, minmax(${isBrand ? '120px' : '105px'}, 1fr))`,
                          marginBottom: '16px',
                        }}
                      >
                        <button
                          type="button"
                          className={`attr-option-empty${isEmpty ? ' attr-option-empty--selected' : ''}`}
                          onClick={() => {
                            handleBatchChange(batch.id, attrDef.stateKey, '');
                            attrNext();
                          }}
                        >
                          <span className="attr-option-empty__icon">⊘</span>
                          <span>{t('wizard.empty') || 'Empty'}</span>
                        </button>

                        {rawAttrOpts.map((opt) => {
                          const selected = batch[attrDef.stateKey] === opt.value;
                          const brandImg = isBrand ? getBrandImage(opt.value) : null;
                          return (
                            <button
                              key={opt.value}
                              type="button"
                              style={{
                                position: 'relative',
                                padding: isBrand ? '12px 8px 10px' : '10px 8px',
                                border: '2px solid',
                                borderRadius: '10px',
                                background: selected && !isBrand ? 'var(--primary)' : 'transparent',
                                borderColor: selected ? 'var(--primary)' : 'var(--border)',
                                boxShadow: selected && isBrand ? '0 0 0 1px var(--primary)' : 'none',
                                color: selected && !isBrand ? '#fff' : 'var(--text)',
                                cursor: 'pointer',
                                fontSize: isBrand ? '11px' : '13px',
                                fontWeight: selected ? 700 : 400,
                                textAlign: 'center',
                                lineHeight: 1.3,
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                gap: '7px',
                                transition: 'border-color 0.12s, background 0.12s',
                              }}
                              onClick={() => {
                                handleBatchChange(batch.id, attrDef.stateKey, opt.value);
                                attrNext();
                              }}
                            >
                              {isBrand && <BrandAvatar src={brandImg} label={opt.label} selected={selected} />}
                              <span>{opt.label}</span>
                            </button>
                          );
                        })}
                      </div>
                    );
                  })()}

                  {/* Text input attribute */}
                  {attrDef.text && (
                    <div className="form-field" style={{ marginBottom: '16px' }}>
                      <input
                        className="app-input"
                        type="text"
                        value={batch[attrDef.stateKey] || ''}
                        placeholder={attrDef.placeholder || t(attrDef.labelKey) || attrDef.label}
                        onChange={(e) => handleBatchChange(batch.id, attrDef.stateKey, e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && attrNext()}
                      />
                    </div>
                  )}

                  {/* Sub-step 1 Nav */}
                  <div className="wizard-nav-row">
                    <button
                      type="button"
                      className="app-button app-button--secondary wizard-nav-btn--sm"
                      onClick={attrPrev}
                    >
                      {t('common.previous')}
                    </button>
                    <button
                      type="button"
                      className="app-button app-button--primary app-button--block wizard-nav-btn--sm"
                      onClick={attrNext}
                    >
                      {attrIdx === ATTR_FIELDS.length - 1 ? `✓ ${t('quality.doneBatch')}` : `${t('common.next')} ➔`}
                    </button>
                  </div>
                </div>
              )}
            </article>
          );
        })}
      </div>

      {/* ── Add Batch Button ── */}
      {canEdit && (
        <div style={{ marginTop: '20px', display: 'flex', justifyContent: 'flex-start' }}>
          <button
            type="button"
            className="app-button app-button--secondary"
            onClick={handleAddBatch}
          >
            {t('quality.addBatch')}
          </button>
        </div>
      )}

      {renderWizardNav()}
    </section>
  );

    if (activeStep === operationalIndex) {
      return (
        <section className="card-panel quality-wizard-card--wide grpo-draft-card">
          <div className="quality-wizard-heading">
            <h1 className="page-title">{t('quality.grpoSteps.operational')}</h1>
            <p className="quality-wizard-subtitle">{t('quality.batchInfoDesc')}</p>
          </div>
          <div className="grpo-status-strip">
            <span className="section-kicker">{t('quality.grpoDraftStatus')}</span>
            <span className={`rr-status-badge rr-status-badge--${draft?.status || 'DRAFT'}`}>{statusLabel(draft?.status)}</span>
          </div>
          {renderSapDocumentInfo()}
          <div className="grpo-review-grid" style={{ marginBottom: '20px' }}>
            {renderInfoItem(t('quality.colInspectionId'), draft?.inspection || '-')}
            {renderInfoItem(t('quality.productName'), `${fmtValue(form.item_code || draft?.item_code)} - ${fmtValue(form.item_name || draft?.item_name)}`)}
            {renderInfoItem(t('quality.grpoQuantity'), `${fmtValue(form.quantity)} ${fmtValue(form.uom_name || form.uom_code || draft?.uom_name || draft?.uom_code)}`)}
            {renderInfoItem(t('quality.selectWarehouse'), form.warehouse_code || '-')}
            {renderInfoItem(t('quality.binLocation'), form.bin_code || '-')}
          </div>
          <div className="quality-form-grid qrev-meta-grid">
            {renderInput({
              field: 'car_number',
              label: t('quality.containerNumber'),
              value: form.car_number || draft?.inspection_context?.car_number || draft?.car_number || '-',
              readOnly: !isManualDraft || !canEdit,
            })}
            <label className="form-field">
              <span>{t('quality.noPacked')} *</span>
              <input
                className={`app-input${fieldError('container_quantity') ? ' app-input--error' : ''}`}
                type="number"
                min="0"
                step="1"
                value={form.container_quantity}
                disabled={!canEdit}
                onChange={(e) => {
                  const val = e.target.value;
                  if (val === '') {
                    updateField('container_quantity', '');
                    return;
                  }
                  if (/^\d+$/.test(val)) {
                    updateField('container_quantity', val);
                  }
                }}
                onKeyDown={(e) => {
                  if (e.key === '.' || e.key === 'e' || e.key === 'E' || e.key === '+' || e.key === '-') {
                    e.preventDefault();
                  }
                }}
                onBlur={() => {
                  if (form.container_quantity === '') {
                    updateField('container_quantity', '0');
                  }
                }}
              />
              {fieldError('container_quantity') && <span className="form-field__hint grpo-field-error">{fieldError('container_quantity')}</span>}
            </label>
            {renderInput({ field: 'posting_date', label: t('quality.postingDate'), type: 'date' })}
            {renderInput({ field: 'document_date', label: t('quality.documentDate'), type: 'date' })}
            {renderInput({ field: 'due_date', label: t('quality.dueDate'), type: 'date' })}
            {renderInput({ field: 'vendor_ref_no', label: t('quality.vendorRefNo'), placeholder: t('quality.vendorRefNoPlaceholder') })}
            {renderInput({ field: 'journal_remark', label: t('quality.journalRemark'), placeholder: t('quality.journalRemarkPlaceholder') })}
            <label className="form-field quality-form-field--full">
              <span>{t('quality.grpoComments')}</span>
              <textarea
                className="app-input"
                rows={3}
                value={form.comments}
                readOnly={!canEdit}
                onChange={(event) => updateField('comments', event.target.value)}
              />
            </label>
          </div>
          {renderWizardNav()}
        </section>
      );
    }

    if (activeStep === batchesIndex) {
      return renderBatchDataStep();
    }

    return (
      <section className="card-panel quality-wizard-card--wide grpo-draft-card">
        <div className="quality-wizard-heading">
          <h1 className="page-title">{t('quality.grpoReviewPostingTitle')}</h1>
          <p className="quality-wizard-subtitle">{t('quality.grpoReviewPostingDesc')}</p>
        </div>
        <div className="grpo-review-grid">
          {renderInfoItem(t('quality.colInspectionId'), draft.inspection)}
          {renderInfoItem(t('quality.grpoDraftStatus'), statusLabel(draft.status))}
          {hasSapDocumentInfo && renderInfoItem(t('grpo.documentStatus'), statusLabel(draft.status))}
          {hasSapDocumentInfo && renderInfoItem(t('quality.sapDocEntry'), draft.sap_doc_entry)}
          {hasSapDocumentInfo && renderInfoItem(t('grpo.referenceNumber'), draft.sap_doc_num)}
          {renderInfoItem(t('quality.vendorName'), `${fmtValue(form.vendor_card_code)} - ${fmtValue(form.vendor_name)}`)}
          {draft?.quotation && renderInfoItem('مرجع الشحن المرتبط', `#${draft.quotation_number || draft.quotation}${draft.quotation_sap_doc_entry ? ` (المرجع: ${draft.quotation_sap_doc_entry})` : ''}`)}
          {renderInfoItem(t('quality.containerNumber'), form.car_number || draft?.inspection_context?.car_number || draft?.car_number || '-')}
          {renderInfoItem(t('quality.noPacked'), form.container_quantity !== undefined && form.container_quantity !== null && form.container_quantity !== '' ? form.container_quantity : (draft?.container_quantity ?? '0'))}
          {renderInfoItem(t('quality.productName'), `${fmtValue(form.item_code || draft?.item_code)} - ${fmtValue(form.item_name || draft?.item_name)}`)}
          {renderInfoItem(t('quality.grpoQuantity'), `${fmtValue(form.quantity)} ${fmtValue(form.uom_name || form.uom_code || draft?.uom_name || draft?.uom_code)}`)}
          {renderInfoItem(t('quality.unitPrice'), form.unit_price)}
          {renderInfoItem(t('quality.postingDate'), form.posting_date)}
          {renderInfoItem(t('quality.documentDate'), form.document_date)}
          {renderInfoItem(t('quality.dueDate'), form.due_date)}
          {renderInfoItem(t('quality.vendorRefNo'), form.vendor_ref_no)}
          {renderInfoItem(t('quality.journalRemark'), form.journal_remark)}
          {renderInfoItem(t('quality.taxCode'), form.tax_code)}
          {renderInfoItem(t('quality.discountPercent'), form.discount_percent)}
          {renderInfoItem(t('quality.location'), getCostCenterDisplay(form.location, costCentersDim1))}
          {renderInfoItem(t('quality.general'), getCostCenterDisplay(form.general, costCentersDim2))}
          {renderInfoItem(t('quality.selectWarehouse'), form.warehouse_code)}
          {renderInfoItem(t('quality.binLocation'), form.bin_code)}
          {renderInfoItem(t('quality.batchNumber'), form.batch_number)}
          {renderInfoItem(t('quality.manufacturingDate'), form.manufacturing_date)}
          {renderInfoItem(t('quality.admissionDate'), form.admission_date)}
          {renderInfoItem(t('quality.expiryDate'), form.expiry_date)}
        </div>

        {/* Batch Allocation Breakdown */}
        {batches.length > 0 && (
          <div className="grpo-review-section" style={{ marginTop: '24px' }}>
            <h3 className="grpo-review-section__title">
              🏷️ {t('quality.batchBreakdown')} ({batches.length})
            </h3>
            <div className="grpo-review-batches-list" style={{ display: 'flex', flexDirection: 'column', gap: '16px', marginTop: '12px' }}>
              {batches.map((batch, bIdx) => (
                <div
                  key={batch.id || bIdx}
                  className="card-panel"
                  style={{ background: 'var(--bg-muted, #f8f9fa)', border: '1px solid var(--border)', borderRadius: '8px', padding: '16px' }}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px', borderBottom: '1px solid var(--border)', paddingBottom: '8px' }}>
                    <strong>{t('quality.batchLabel', bIdx + 1)}: {batch.batch_number || '-'}</strong>
                    <span style={{ fontWeight: 600, color: 'var(--primary)' }}>
                      {fmtValue(batch.quantity)} {form.uom_name || form.uom_code || draft?.uom_name || draft?.uom_code || ''}
                    </span>
                  </div>
                  <div className="details-grid details-grid--sm" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))', gap: '12px' }}>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">📍</span>{t('quality.binLocation')}</span><div className="detail-item__value">{batch.bin_location_code || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">📅</span>{t('quality.manufacturingDate')}</span><div className="detail-item__value">{batch.manufacturing_date || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">📅</span>{t('quality.admissionDate')}</span><div className="detail-item__value">{batch.admission_date || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">📅</span>{t('quality.expiryDate')}</span><div className="detail-item__value">{batch.expiry_date || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">🏢</span>{t('quality.batchAttrs.vendor')}</span><div className="detail-item__value">{batch.vendor || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">🏷️</span>{t('quality.batchAttrs.part')}</span><div className="detail-item__value">{batch.part || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">🏢</span>{t('quality.batchAttrs.company')}</span><div className="detail-item__value">{batch.company || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">📅</span>{t('quality.batchAttrs.season')}</span><div className="detail-item__value">{batch.season || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">🏷️</span>{t('quality.batchAttrs.batchAttribute1')}</span><div className="detail-item__value">{batch.batch_attribute_1 || '-'}</div></div>
                    <div className="detail-item detail-item--sm"><span className="detail-item__label"><span className="meta-label-icon" aria-hidden="true">🏷️</span>{t('quality.batchAttrs.batchAttribute2')}</span><div className="detail-item__value">{batch.batch_attribute_2 || '-'}</div></div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        <div className="grpo-preview-actions">
          <button
            type="button"
            className="app-button app-button--secondary app-button--compact"
            onClick={handlePreviewPosting}
            disabled={previewLoading || !canPostToSap}
          >
            {previewLoading ? t('common.pleaseWait') : t('quality.checkGrpoPostingReadiness')}
          </button>
        </div>

        {postingPreview && (
          <div className="feedback-message feedback-message--info grpo-draft-card__notice">
            {t('quality.grpoPostingReadinessReady')}
          </div>
        )}

        {Object.keys(errors).length > 0 && (
          <div className="feedback-message feedback-message--error grpo-validation-summary">
            {t('quality.validationErrorsFound')}
          </div>
        )}
        {renderWizardNav()}
      </section>
    );
  };

  return (
    <div className="page-shell quality-wizard grpo-draft-page">
      <header className="page-header grpo-wizard-page-header">
        <div>
          <span className="section-kicker">
            {isManual
              ? `${t('grpo.continuousWorkflow')} • ${t('grpo.manualPhaseTitle')}`
              : isStandaloneGrpo
                ? (t('grpo.kicker') || 'Receiving')
                : t('quality.purchaseGrpoKicker')}
          </span>
          <h1 className="page-title">
            {isManual
              ? t('grpo.manualReceivingTitle')
              : postedViewOnly
                ? t('quality.purchaseGrpoDocumentTitle')
                : t('quality.purchaseGrpoDraftTitle')}
          </h1>
        </div>
        <div className="grpo-header-actions">
          {!postedViewOnly && !isPosted && Boolean(draft) && (
            <button
              type="button"
              className="app-button app-button--secondary qrev-header-button"
              onClick={loadDraft}
              disabled={saving || approving || posting || loading}
            >
              {t('quality.reloadDraft')}
            </button>
          )}
          <button
            type="button"
            className="app-button app-button--secondary qrev-header-button"
            onClick={handleBack}
          >
            {t('common.back')}
          </button>
        </div>
      </header>

      {loading ? (
        <section className="card-panel quality-wizard-card--wide grpo-draft-card">
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '3rem 1rem', gap: '1.25rem' }}>
            <AppSpinner size="md" label={t('common.loading')} />
            <LoadingSkeleton rows={4} style={{ width: '100%', maxWidth: '600px' }} />
          </div>
        </section>
      ) : (!draft && !isManualCreate) ? (
        <section className="card-panel quality-wizard-card--wide grpo-draft-card">
          <div className="feedback-message feedback-message--error">
            {t('quality.grpoDraftNotFound')}
          </div>
        </section>
      ) : isInvalidPostedDocumentView ? (
        <section className="card-panel quality-wizard-card--wide grpo-draft-card">
          <div className="feedback-message feedback-message--error">
            {t('quality.grpoDocumentNotPosted')}
          </div>
        </section>
      ) : isPosted ? (
        renderPostedSummary()
      ) : (
        <>
          {isManual && (
            <ContinuousPhaseTracker
              activeStep={activeStep}
              draft={draft}
              t={t}
            />
          )}

          <div className="quality-stepper grpo-stepper">
            <Stepper
              activeStep={activeStep}
              alternativeLabel
              nonLinear
              className="quality-mui-stepper"
            >
              {wizardSteps.map(({ id, labelKey, icon }, index) => {
                const canClick = index <= maxReachedStep;
                return (
                  <Step key={id} completed={index < activeStep}>
                    <StepButton
                      disabled={!canClick}
                      onClick={() => goToStep(index)}
                    >
                      <StepLabel icon={icon} slots={{ stepIcon: GrpoStepIcon }}>
                        {t(labelKey)}
                      </StepLabel>
                    </StepButton>
                  </Step>
                );
              })}
            </Stepper>
          </div>

          <div className="quality-step-viewport grpo-step-viewport">
            {renderCurrentStep()}
          </div>
        </>
      )}

      {/* Hidden printable sheet for GRPO direct print */}
      {printingRecord && (
        <div
          className="qrev-print-report"
          aria-hidden="true"
          style={{ display: 'none' }}
          ref={printContainerRef}
        >
          <div
            className="a4-print-sheet"
            style={{
              position: 'relative',
              width: '100%',
              minHeight: '297mm',
              boxSizing: 'border-box',
              direction: 'rtl',
            }}
          >
            {/* Top Logo Section */}
            <div className="report-print-logo-row">
              <div className="report-header-brand">
                <img
                  src={egastLogo}
                  alt="EGAST Group"
                  className="report-header-logo"
                />
                <div className="report-header-text">
                  <h2>الشركة المصرية للخدمات الزراعية (إيجاست)</h2>
                  <p>SHIPPING &amp; RECEIVING OPERATIONS</p>
                </div>
              </div>
              <div className="report-doc-no">
                <span className="report-badge">مستند استلام مسجل</span>
                <PrintDocumentBarcode identification={printingRecord._printIdentification} />
              </div>
            </div>

            {/* Main Title */}
            <div className="report-main-title">
              <h1>مستند استلام</h1>
              <span>GOODS RECEIVING DOCUMENT</span>
            </div>

            {/* Metadata Grid */}
            <div className="report-info-grid">
              <div className="info-cell">
                <span className="cell-lbl">رقم المرجع الداخلي:</span>{' '}
                <strong>#{printingRecord.id}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">رقم المستند (SAP):</span>{' '}
                <strong>{printingRecord.sap_doc_num || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">DocEntry (SAP):</span>{' '}
                <strong>{printingRecord.sap_doc_entry || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">رقم التشغيلة:</span>{' '}
                <strong>{printingRecord.batch_number || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">رقم السيارة:</span>{' '}
                <strong>{printingRecord.car_number || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">المورد:</span>{' '}
                <strong>{printingRecord.vendor_name || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">كود المورد:</span>{' '}
                <strong>{printingRecord.vendor_card_code || '-'}</strong>
              </div>
              {printingRecord.vendor_ref_no && (
                <div className="info-cell">
                  <span className="cell-lbl">رقم مرجع المورد:</span>{' '}
                  <strong>{printingRecord.vendor_ref_no}</strong>
                </div>
              )}
              <div className="info-cell">
                <span className="cell-lbl">كود الصنف:</span>{' '}
                <strong>{printingRecord.item_code || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">اسم الصنف:</span>{' '}
                <strong>{printingRecord.item_name || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">الكمية المستلمة:</span>{' '}
                <strong>
                  {Number(printingRecord.quantity || 0).toLocaleString()} {printingRecord.uom_name || printingRecord.uom_code || 'KG'}
                </strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">المستودع:</span>{' '}
                <strong>{printingRecord.warehouse_code || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">الموقع:</span>{' '}
                <strong>{printingRecord.bin_code || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">تاريخ الاستلام:</span>{' '}
                <strong>{printingRecord.posted_at ? String(printingRecord.posted_at).slice(0, 10) : (printingRecord.posting_date || '-')}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">تاريخ المستند:</span>{' '}
                <strong>{printingRecord.document_date || '-'}</strong>
              </div>
              <div className="info-cell">
                <span className="cell-lbl">حالة المستند:</span>{' '}
                <strong style={{ color: '#16a34a' }}>تم تسجيل الاستلام في SAP</strong>
              </div>
            </div>

            {/* Line Items Table */}
            <h4 className="report-section-header" style={{ marginTop: '24px' }}>
              بيانات البنود المستلمة (Received Items)
            </h4>
            <table
              className="excel-matrix-table"
              style={{
                width: '100%',
                borderCollapse: 'collapse',
                marginBottom: '24px',
                fontSize: '12px',
              }}
            >
              <thead>
                <tr style={{ background: '#f1f5f9' }}>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center', width: '40px' }}>#</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'start' }}>كود الصنف</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'start' }}>الوصف / المنتج</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>المخزن</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>الموقع</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>رقم التشغيلة</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'end' }}>الكمية</th>
                  <th style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>الوحدة</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>1</td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'start', fontFamily: 'monospace' }}>
                    {printingRecord.item_code || '-'}
                  </td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'start', fontWeight: 600 }}>
                    {printingRecord.item_name || '-'}
                  </td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>
                    {printingRecord.warehouse_code || '-'}
                  </td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>
                    {printingRecord.bin_code || '-'}
                  </td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center', fontFamily: 'monospace' }}>
                    {printingRecord.batch_number || '-'}
                  </td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'end', fontWeight: 700 }}>
                    {Number(printingRecord.quantity || 0).toLocaleString()}
                  </td>
                  <td style={{ border: '1px solid #cbd5e1', padding: '8px', textAlign: 'center' }}>
                    {printingRecord.uom_name || printingRecord.uom_code || 'KG'}
                  </td>
                </tr>
              </tbody>
            </table>

            {/* Signatures */}
            <div className="report-signature-row" style={{ marginTop: '48px' }}>
              <div className="sig-column">
                <p>أمين المستودع (المستلم)</p>
                <div className="sig-line" />
                <span className="sig-date-placeholder">التوقيع والتاريخ</span>
              </div>
              <div className="sig-column">
                <p>مسؤول فحص الجودة</p>
                <div className="sig-line" />
                <span className="sig-date-placeholder">التوقيع والتاريخ</span>
              </div>
              <div className="sig-column">
                <p>مدير إدارة المشتريات / المخازن</p>
                <div className="sig-line" />
                <span className="sig-date-placeholder">التوقيع والتاريخ</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default PurchaseGRPODraftPage;

import { warehouseSearch, farmSearch, itemSearch as remoteItemSearch } from '../services/masterDataSearch';
import API from '../services/api';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Step, StepButton, StepLabel, Stepper, CircularProgress } from '@mui/material';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { useI18n } from '../contexts/I18nContext';
import { useAuth } from '../contexts/AuthContext';
import { canManagePurchaseQuotation } from '../utils/roles';
import { useToast } from '../components/ui/ToastProvider';
import SearchableSelect from '../components/ui/SearchableSelect';
import useCostCenterOptions from '../hooks/useCostCenterOptions';
import {
  approvePurchaseQuotationDraftForPosting,
  cancelPurchaseQuotationDraft,
  loadCurrencies,
  loadPurchaseQuotationDraft,
  loadQualityItemGroups,
  postPurchaseQuotationToSAP,
  previewPurchaseQuotationPosting,
  savePurchaseQuotationDraft,
} from '../services/purchaseQuotationService';
import '../styles/pages/receipt-review.css';
import '../styles/pages/quality-inspection.css';
import { getProductIcon } from '../utils/productIcon';

const EDITABLE_STATUSES = new Set(['DRAFT', 'POSTING_FAILED']);

const STEPS = [
  { id: 'vehicle', labelKey: 'purchaseQuotation.steps.vehicle', icon: '1' },
  { id: 'vendor', labelKey: 'purchaseQuotation.steps.vendor', icon: '2' },
  { id: 'header', labelKey: 'purchaseQuotation.steps.header', icon: '3' },
  { id: 'itemGroup', labelKey: 'purchaseQuotation.steps.itemGroup', icon: '4' },
  { id: 'item', labelKey: 'purchaseQuotation.steps.item', icon: '5' },
  { id: 'itemDetails', labelKey: 'purchaseQuotation.steps.itemDetails', icon: '6' },
  { id: 'logistics', labelKey: 'purchaseQuotation.steps.logistics', icon: '7' },
  { id: 'financial', labelKey: 'purchaseQuotation.steps.financial', icon: '8' },
  { id: 'review', labelKey: 'purchaseQuotation.steps.review', icon: '9' },
];

const getTodayDate = () => new Date().toISOString().split('T')[0];

const VENDOR_STORAGE_PREFIX = 'purchaseQuotationVendor:';

function getStoredVendor(draftId) {
  if (!draftId) return null;
  try {
    const raw = sessionStorage.getItem(`${VENDOR_STORAGE_PREFIX}${draftId}`);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object' && parsed.cardCode) {
      return parsed;
    }
  } catch (err) {
    console.warn('Failed to read vendor from sessionStorage:', err);
  }
  return null;
}

function saveVendorToStorage(draftId, cardCode, name, currency) {
  if (!draftId || !cardCode) return;
  try {
    sessionStorage.setItem(
      `${VENDOR_STORAGE_PREFIX}${draftId}`,
      JSON.stringify({
        cardCode: String(cardCode).trim(),
        name: String(name || cardCode).trim(),
        currency: currency ? String(currency).trim() : '',
      })
    );
  } catch (err) {
    console.warn('Failed to save vendor to sessionStorage:', err);
  }
}

function clearStoredVendor(draftId) {
  if (!draftId) return;
  try {
    sessionStorage.removeItem(`${VENDOR_STORAGE_PREFIX}${draftId}`);
  } catch (err) {
    console.warn('Failed to clear vendor from sessionStorage:', err);
  }
}

function GrpoStepIcon({ icon, active, completed }) {
  const className = [
    'quality-mui-step-icon',
    active ? 'quality-mui-step-icon--active' : '',
    completed ? 'quality-mui-step-icon--completed' : '',
  ].filter(Boolean).join(' ');

  return <span className={className}>{completed ? '✓' : icon}</span>;
}

function createDefaultLine() {
  const today = getTodayDate();
  return {
    item_code: '',
    item_description: '',
    item_group_code: '',
    quoted_date: today,
    required_date: today,
    quoted_qty: 1,
    required_qty: 1,
    uom_code: 'PCS',
    unit_price: 0,
    discount_percent: 0,
    tax_code: '',
    warehouse_code: '',
    location_code: '',
    costing_code: '',
    line_total: 0,
  };
}

function PurchaseQuotationDraftPage({ postedViewOnly = false }) {
  const { user } = useAuth();
  const canAdministerQuotation = canManagePurchaseQuotation(user);
  const { draftId } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const { t, lang } = useI18n();
  const toast = useToast();

  const [draft, setDraft] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [approving, setApproving] = useState(false);
  const [posting, setPosting] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [verifyingPayload, setVerifyingPayload] = useState(false);
  const [errors, setErrors] = useState({});
  const [activeStep, setActiveStep] = useState(0);
  const [maxReachedStep, setMaxReachedStep] = useState(0);

  // Master data
  const warehouses = [];
  const {
    costCentersDim1,
    costCentersDim2,
    costCentersLoading,
    costCenterError1,
    costCenterError2,
    reloadCostCenter,
  } = useCostCenterOptions();
  const [currencies, setCurrencies] = useState([]);
  const [farms, setFarms] = useState([]);
  const [itemGroups, setItemGroups] = useState([]);
  const [loadingItemGroups, setLoadingItemGroups] = useState(true);
  const [, setItemSearchMap] = useState({});
  const [postingPreview, setPostingPreview] = useState(null);

  // Default Allocation (can be bulk applied to all lines)
  const [defaultWarehouse, setDefaultWarehouse] = useState('');
  const [defaultLocation, setDefaultLocation] = useState('');
  const [defaultCostCenter, setDefaultCostCenter] = useState('');

  // Form State - Vehicle & Container
  const [vehicleNumber, setVehicleNumber] = useState('');
  const [containerQuantity, setContainerQuantity] = useState('0');

  // Form State - Header
  const [vendorCardCode, setVendorCardCode] = useState('');
  const [vendorName, setVendorName] = useState('');
  const vendorCardCodeRef = useRef(vendorCardCode);
  const vendorNameRef = useRef(vendorName);

  const tRef = useRef(t);
  tRef.current = t;
  const toastRef = useRef(toast);
  toastRef.current = toast;

  // Synchronize refs with state immediately
  useEffect(() => {
    if (vendorCardCode) {
      vendorCardCodeRef.current = vendorCardCode;
    }
  }, [vendorCardCode]);

  useEffect(() => {
    if (vendorName) {
      vendorNameRef.current = vendorName;
    }
  }, [vendorName]);

  const [contactPersonCode, setContactPersonCode] = useState('');
  const [vendorRefNo, setVendorRefNo] = useState('');
  const [currency, setCurrency] = useState('EGP');
  const [groupNo, setGroupNo] = useState('');
  const [postingDate, setPostingDate] = useState(getTodayDate());
  const [validUntil, setValidUntil] = useState(getTodayDate());
  const [documentDate, setDocumentDate] = useState(getTodayDate());
  const [requiredDate, setRequiredDate] = useState(getTodayDate());
  const [buyerCode, setBuyerCode] = useState('');
  const [ownerCode, setOwnerCode] = useState('');

  // Form State - Logistics & Remarks
  const [journalRemark, setJournalRemark] = useState('Purchase Quotation');
  const [remarks, setRemarks] = useState('');
  const [discountPercent, setDiscountPercent] = useState('0');

  // Form State - Lines
  const [lines, setLines] = useState([createDefaultLine()]);

  const isPosted = draft?.status === 'POSTED';
  const canEdit = draft && EDITABLE_STATUSES.has(draft.status) && !postedViewOnly;

  const getEffectiveVendorCode = useCallback(() => {
    // 1. React state
    if (vendorCardCode && String(vendorCardCode).trim()) {
      return String(vendorCardCode).trim();
    }
    // 2. Synchronous ref
    if (vendorCardCodeRef.current && String(vendorCardCodeRef.current).trim()) {
      const code = String(vendorCardCodeRef.current).trim();
      setVendorCardCode(code);
      return code;
    }
    // 3. Current draft
    if (draft?.vendor_card_code && String(draft.vendor_card_code).trim()) {
      const code = String(draft.vendor_card_code).trim();
      setVendorCardCode(code);
      vendorCardCodeRef.current = code;
      return code;
    }
    // 4. Draft-scoped sessionStorage
    const stored = getStoredVendor(draftId);
    if (stored?.cardCode) {
      const code = String(stored.cardCode).trim();
      setVendorCardCode(code);
      vendorCardCodeRef.current = code;
      if (stored.name && !vendorNameRef.current) {
        setVendorName(stored.name);
        vendorNameRef.current = stored.name;
      }
      return code;
    }
    return '';
  }, [draft?.vendor_card_code, draftId, vendorCardCode]);

  const getEffectiveVendorName = useCallback(() => {
    if (vendorName && String(vendorName).trim()) {
      return String(vendorName).trim();
    }
    if (vendorNameRef.current && String(vendorNameRef.current).trim()) {
      const name = String(vendorNameRef.current).trim();
      setVendorName(name);
      return name;
    }
    if (draft?.vendor_name && String(draft.vendor_name).trim()) {
      const name = String(draft.vendor_name).trim();
      setVendorName(name);
      vendorNameRef.current = name;
      return name;
    }
    const stored = getStoredVendor(draftId);
    if (stored?.name) {
      const name = String(stored.name).trim();
      setVendorName(name);
      vendorNameRef.current = name;
      return name;
    }
    return '';
  }, [draft?.vendor_name, draftId, vendorName]);

  const handleSelectVendor = useCallback((farmOrCode, farmNameParam, farmCurrencyParam) => {
    if (!canEdit) return;

    let code = '';
    let name = '';
    let vCurr = '';

    if (farmOrCode && typeof farmOrCode === 'object') {
      code = farmOrCode.code || farmOrCode.farmCode || farmOrCode.CardCode || '';
      name = farmOrCode.name || farmOrCode.farmName || farmOrCode.CardName || code;
      vCurr = farmOrCode.currency ? String(farmOrCode.currency).trim() : '';
    } else {
      code = farmOrCode || '';
      name = farmNameParam || code;
      vCurr = farmCurrencyParam ? String(farmCurrencyParam).trim() : '';
    }

    if (!code) return;

    // 1. Update React state immediately
    setVendorCardCode(code);
    setVendorName(name);

    // 2. Update synchronous refs immediately
    vendorCardCodeRef.current = code;
    vendorNameRef.current = name;

    // 3. Save Vendor to draft-scoped sessionStorage
    saveVendorToStorage(draftId, code, name, vCurr);

    // 4. Update currency if fixed SAP currency
    let activeCurrency = currency;
    if (vCurr && vCurr !== '##') {
      activeCurrency = vCurr;
      setCurrency(vCurr);
    }

    // 5. Persist the Vendor to the backend when safe
    if (draftId) {
      savePurchaseQuotationDraft(draftId, {
        vendor_card_code: code,
        vendor_name: name,
        currency: activeCurrency,
      })
        .then((updated) => {
          if (updated) {
            setDraft((prev) => ({ ...prev, ...updated }));
          }
        })
        .catch((err) => {
          console.warn('Silent auto-save of vendor selection failed:', err);
        });
    }
  }, [canEdit, currency, draftId]);

  const goToStep = (stepIdx) => {
    const trimmedVehicle = String(vehicleNumber || '').trim();
    if (trimmedVehicle.length > 11) {
      toast.error(
        t('purchaseQuotation.invalidVehicleNumber') ||
        (lang === 'ar' ? 'رقم العربية لا يمكن أن يتجاوز 11 حرفاً.' : 'Vehicle number cannot exceed 11 characters.')
      );
      return;
    }
    const qtyNum = containerQuantity === '' ? 0 : Number(containerQuantity);
    if (isNaN(qtyNum) || !Number.isInteger(qtyNum) || qtyNum < 0) {
      toast.error(
        t('purchaseQuotation.invalidContainerQty') ||
        (lang === 'ar' ? 'كمية الكونتينر يجب أن تكون رقماً صحيحاً غير سالب.' : 'Container quantity must be a whole non-negative number.')
      );
      return;
    }
    const effectiveVendor = getEffectiveVendorCode();
    if (stepIdx > 1 && !effectiveVendor) {
      toast.error(t('purchaseQuotation.vendorRequired') || (lang === 'ar' ? 'يرجى اختيار مورد للمتابعة.' : 'Please select a vendor to proceed.'));
      return;
    }
    if (effectiveVendor && !vendorCardCode) {
      setVendorCardCode(effectiveVendor);
      vendorCardCodeRef.current = effectiveVendor;
      const effName = getEffectiveVendorName();
      if (effName) {
        setVendorName(effName);
        vendorNameRef.current = effName;
      }
    }
    if (stepIdx > 3) {
      const hasMissingGroup = lines.some((l) => !String(l.item_group_code || '').trim());
      if (hasMissingGroup) {
        toast.error(
          t('purchaseQuotation.itemGroupRequired') ||
          (lang === 'ar' ? 'يرجى اختيار مجموعة الأصناف لجميع السطور للمتابعة.' : 'Please select an Item Group for all lines to proceed.')
        );
        return;
      }
    }
    if (stepIdx > 4) {
      const hasMissingItem = lines.some((l) => !String(l.item_code || '').trim());
      if (hasMissingItem) {
        toast.error(
          t('purchaseQuotation.itemRequired') ||
          (lang === 'ar' ? 'يرجى اختيار رقم الصنف (Item No.) لجميع السطور للمتابعة.' : 'Please select an Item No. for all lines to proceed.')
        );
        return;
      }
    }
    if (stepIdx > 5) {
      const hasInvalidQty = lines.some((l) => Number(l.quoted_qty || 0) <= 0 || Number(l.required_qty || 0) <= 0);
      if (hasInvalidQty) {
        toast.error(
          t('purchaseQuotation.invalidQuantities') ||
          (lang === 'ar' ? 'يرجى إدخال كميات صحيحة لجميع السطور للمتابعة.' : 'Please enter valid quantities for all lines to proceed.')
        );
        return;
      }
    }
    setActiveStep(stepIdx);
    if (stepIdx > maxReachedStep) {
      setMaxReachedStep(stepIdx);
    }
  };

  const loadDraftData = useCallback(async () => {
    if (!draftId) return;
    setLoading(true);
    try {
      const data = await loadPurchaseQuotationDraft(draftId);
      setDraft(data);
      if (data) {
        // Non-destructive vendor resolution
        const incomingVendor = (data.vendor_card_code || '').trim();
        const incomingVendorName = (data.vendor_name || '').trim();
        const incomingCurrency = (data.currency || '').trim();

        if (incomingVendor) {
          // Backend has valid vendor -> sync state + refs + storage
          setVendorCardCode(incomingVendor);
          vendorCardCodeRef.current = incomingVendor;
          setVendorName(incomingVendorName);
          vendorNameRef.current = incomingVendorName;
          saveVendorToStorage(draftId, incomingVendor, incomingVendorName, incomingCurrency);
        } else {
          // Backend returned empty vendor. Check effective local vendor first!
          const localEffective = vendorCardCodeRef.current || vendorCardCode || getStoredVendor(draftId)?.cardCode || '';
          const localName = vendorNameRef.current || vendorName || getStoredVendor(draftId)?.name || '';
          if (localEffective) {
            // Keep local vendor! DO NOT destroy it with empty backend response!
            setVendorCardCode(localEffective);
            vendorCardCodeRef.current = localEffective;
            if (localName) {
              setVendorName(localName);
              vendorNameRef.current = localName;
            }
            saveVendorToStorage(draftId, localEffective, localName, incomingCurrency || currency);
          } else {
            // Genuinely no vendor anywhere
            setVendorCardCode('');
            vendorCardCodeRef.current = '';
            setVendorName('');
            vendorNameRef.current = '';
            clearStoredVendor(draftId);
          }
        }

        setVehicleNumber(data.vehicle_number || '');
        setContainerQuantity(data.container_quantity !== undefined && data.container_quantity !== null ? String(data.container_quantity) : '0');
        setContactPersonCode(data.contact_person_code || '');
        setVendorRefNo(data.vendor_ref_no || '');
        if (data.currency) setCurrency(data.currency);
        setGroupNo(data.group_no || '');
        setPostingDate(data.posting_date || getTodayDate());
        setValidUntil(data.valid_until || getTodayDate());
        setDocumentDate(data.document_date || getTodayDate());
        setRequiredDate(data.required_date || getTodayDate());
        setBuyerCode(data.buyer_code || '');
        setOwnerCode(data.owner_code || '');
        setJournalRemark(data.journal_remark || 'Purchase Quotation');
        setRemarks(data.remarks || '');
        setDiscountPercent(String(data.discount_percent ?? 0));

        const parsedLines = Array.isArray(data.lines) && data.lines.length > 0
          ? data.lines.map((l) => ({
              ...createDefaultLine(),
              ...l,
              item_code: l.item_code || '',
              item_description: l.item_description || l.item_name || '',
              item_group_code: l.item_group_code ? String(l.item_group_code) : '',
              quoted_qty: Number(l.quoted_qty ?? 1),
              required_qty: Number(l.required_qty ?? 1),
              quoted_date: l.quoted_date || data.posting_date || getTodayDate(),
              required_date: l.required_date || data.required_date || data.valid_until || getTodayDate(),
              unit_price: Number(l.unit_price ?? 0),
              discount_percent: Number(l.discount_percent ?? 0),
              warehouse_code: l.warehouse_code || '',
              location_code: l.location_code !== null && l.location_code !== undefined ? String(l.location_code) : (l.costing_code || ''),
              costing_code: l.costing_code || '',
              costing_code2: l.costing_code2 || '',
              uom_code: l.uom_code || 'PCS',
            }))
          : [createDefaultLine()];
        // Verify saved selections with one exact lookup per distinct item, never a group catalog.
        const loadedSelections = {};
        await Promise.all([...new Set(parsedLines.filter((line) => line.item_code && line.item_group_code)
          .map((line) => `${line.item_group_code}::${line.item_code}`))].map(async (selection) => {
          const [group, code] = selection.split('::');
          try {
            const response = await API.get('/quality/items/', { params: { lookup: 1, code, item_group_code: group, limit: 1 } });
            loadedSelections[selection] = response.data?.items || [];
          } catch { /* Preserve the saved draft on discovery failure; posting validation remains authoritative. */ }
        }));

        // Restore saved item only if consistent with group
        const verifiedLines = parsedLines.map((l) => {
          if (!l.item_group_code) {
            return {
              ...l,
              item_code: '',
              item_description: '',
            };
          }
          if (l.item_code) {
            const itemsInGroup = loadedSelections[`${l.item_group_code}::${l.item_code}`];
            if (Array.isArray(itemsInGroup)) {
              const itemMatches = itemsInGroup.some((it) => String(it.item_code) === String(l.item_code));
              if (!itemMatches) {
                return {
                  ...l,
                  item_code: '',
                  item_description: '',
                };
              }
            }
          }
          return l;
        });

        setLines(verifiedLines);

        if (parsedLines.length > 0) {
          if (parsedLines[0].warehouse_code) setDefaultWarehouse(parsedLines[0].warehouse_code);
          if (parsedLines[0].location_code) {
            setDefaultLocation(String(parsedLines[0].location_code));
          } else if (parsedLines[0].costing_code) {
            setDefaultLocation(String(parsedLines[0].costing_code));
          }
          if (parsedLines[0].costing_code2) {
            setDefaultCostCenter(String(parsedLines[0].costing_code2));
          } else if (parsedLines[0].costing_code && String(parsedLines[0].costing_code).startsWith('210')) {
            setDefaultCostCenter(String(parsedLines[0].costing_code));
          }
        }

        if (data.status === 'POSTED') {
          setActiveStep(8);
          setMaxReachedStep(8);
        } else if (data.vendor_card_code || vendorCardCodeRef.current || getStoredVendor(draftId)?.cardCode) {
          let reached = 2;
          const hasGroup = verifiedLines.length > 0 && verifiedLines.every((l) => String(l.item_group_code || '').trim());
          if (hasGroup) reached = 3;
          const hasItem = hasGroup && verifiedLines.every((l) => String(l.item_code || '').trim());
          if (hasItem) reached = 4;
          const hasQty = hasItem && verifiedLines.every((l) => Number(l.quoted_qty || 0) > 0 && Number(l.required_qty || 0) > 0);
          if (hasQty) reached = 5;
          setMaxReachedStep((prev) => Math.max(prev, reached));
        }
      }
    } catch (err) {
      console.error('Failed to load draft:', err);
      toastRef.current?.error(tRef.current?.('purchaseQuotation.loadFailed') || 'Failed to load draft');
    } finally {
      setLoading(false);
    }
  }, [currency, draftId]);

  useEffect(() => {
    loadDraftData();
  }, [loadDraftData]);

  // Load SAP master data on mount
  useEffect(() => {
    let isMounted = true;
    loadCurrencies()
      .then((res) => {
        if (isMounted) setCurrencies(Array.isArray(res) ? res : []);
      })
      .catch((err) => console.error('Failed to load currencies:', err));

    setLoadingItemGroups(true);
    loadQualityItemGroups()
      .then((res) => {
        if (isMounted) {
          const groups = Array.isArray(res) ? res : [];
          setItemGroups(groups);
        }
      })
      .catch((err) => console.error('Failed to load item groups:', err))
      .finally(() => {
        if (isMounted) setLoadingItemGroups(false);
      });

    return () => {
      isMounted = false;
    };
  }, []);

  const selectedVendor = useMemo(() => {
    return farms.find((f) => String(f.code || f.farmCode) === String(vendorCardCode)) || null;
  }, [farms, vendorCardCode]);

  const vendorSapCurrency = useMemo(() => {
    const c = selectedVendor?.currency;
    return c ? String(c).trim() : '';
  }, [selectedVendor]);

  const isVendorCurrencyLocked = useMemo(() => {
    return Boolean(vendorSapCurrency && vendorSapCurrency !== '##');
  }, [vendorSapCurrency]);

  // Synchronize currency when a vendor with fixed currency is selected or loaded
  useEffect(() => {
    if (canEdit && isVendorCurrencyLocked && vendorSapCurrency) {
      if (currency !== vendorSapCurrency) {
        setCurrency(vendorSapCurrency);
      }
    }
  }, [canEdit, isVendorCurrencyLocked, vendorSapCurrency, currency]);

  // Live Totals Calculation
  const totals = useMemo(() => {
    let subtotal = 0;
    let taxTotal = 0;

    const calculatedLines = lines.map((line) => {
      const qQty = Number(line.quoted_qty || 0);
      const price = Number(line.unit_price || 0);
      const disc = Number(line.discount_percent || 0);
      const gross = qQty * price;
      const net = gross * (1 - disc / 100);
      const taxRate = Number(line.tax_rate || 0);
      const tax = net * (taxRate / 100);

      subtotal += net;
      taxTotal += tax;
      return { ...line, line_total: net, tax_amount: tax };
    });

    const hdrDiscPct = Number(discountPercent || 0);
    const hdrDiscAmt = subtotal * (hdrDiscPct / 100);
    const totalDue = Math.max(0, subtotal - hdrDiscAmt + taxTotal);

    return {
      subtotal,
      hdrDiscAmt,
      taxTotal,
      totalDue,
      calculatedLines,
    };
  }, [lines, discountPercent]);

  const handleLineChange = (index, field, value) => {
    setLines((prev) => {
      const next = [...prev];
      next[index] = { ...next[index], [field]: value };
      return next;
    });
  };

  const handleAddLine = () => {
    setLines((prev) => [
      ...prev,
      {
        ...createDefaultLine(),
        item_group_code: '',
        quoted_date: postingDate,
        required_date: requiredDate || validUntil,
        warehouse_code: defaultWarehouse,
        location_code: defaultLocation,
        costing_code: defaultLocation,
        costing_code2: defaultCostCenter,
      },
    ]);
  };

  const handleRemoveLine = (index) => {
    setLines((prev) => (prev.length > 1 ? prev.filter((_, i) => i !== index) : prev));
  };

  const applyLogisticsToAllLines = () => {
    setLines((prev) =>
      prev.map((l) => ({
        ...l,
        warehouse_code: defaultWarehouse || l.warehouse_code,
        location_code: defaultLocation || l.location_code,
        costing_code: defaultLocation || l.costing_code,
        costing_code2: defaultCostCenter || l.costing_code2,
      }))
    );
    toast.success(lang === 'ar' ? 'تم تطبيق إعدادات التوزيع على جميع السطور' : 'Applied logistics to all lines.');
  };

  const collectPayload = () => {
    const effectiveVendor = getEffectiveVendorCode();
    const effectiveVendorName = getEffectiveVendorName();
    return {
      vehicle_number: (vehicleNumber || '').trim(),
      container_quantity: Math.max(0, parseInt(containerQuantity || '0', 10) || 0),
      vendor_card_code: effectiveVendor,
      vendor_name: effectiveVendorName,
      contact_person_code: contactPersonCode ? Number(contactPersonCode) : null,
      vendor_ref_no: vendorRefNo,
      currency,
      group_no: groupNo,
      posting_date: postingDate,
      valid_until: validUntil,
      document_date: documentDate,
      required_date: requiredDate,
      buyer_code: buyerCode ? Number(buyerCode) : null,
      owner_code: ownerCode ? Number(ownerCode) : null,
      journal_remark: journalRemark,
      remarks,
      ship_to_address: '',
      pay_to_address: '',
      discount_percent: Number(discountPercent || 0),
      freight: 0,
      rounding: 0,
      lines: lines.map((l) => {
        const locCode = l.location_code || defaultLocation || '';
        const genCode = l.costing_code2 || (l.costing_code && l.costing_code !== locCode ? l.costing_code : '') || defaultCostCenter || '';
        return {
          item_code: l.item_code,
          item_description: l.item_description || l.item_name || '',
          item_group_code: l.item_group_code || '',
          quoted_date: l.quoted_date || postingDate,
          required_date: l.required_date || requiredDate || validUntil,
          quoted_qty: Number(l.quoted_qty || 1),
          required_qty: Number(l.required_qty || 1),
          uom_code: l.uom_code || 'PCS',
          unit_price: Number(l.unit_price || 0),
          discount_percent: Number(l.discount_percent || 0),
          tax_code: l.tax_code || '',
          warehouse_code: l.warehouse_code || defaultWarehouse || '',
          location_code: locCode,
          costing_code: locCode,
          cost_center_dimension: 1,
          costing_code2: genCode,
        };
      }),
    };
  };

  const handleSave = async (quiet = false) => {
    if (!draftId || !canEdit) return null;
    setSaving(true);
    setErrors({});
    try {
      const payload = collectPayload();
      const updated = await savePurchaseQuotationDraft(draftId, payload);
      setDraft(updated);
      if (updated?.vendor_card_code) {
        saveVendorToStorage(draftId, updated.vendor_card_code, updated.vendor_name, updated.currency);
      }
      if (!quiet) {
        toast.success(t('purchaseQuotation.draftSaved'));
      }
      return updated;
    } catch (err) {
      console.error('Save failed:', err);
      if (err.response?.data?.errors) {
        setErrors(err.response.data.errors);
      }
      if (!quiet) {
        toast.error(err.response?.data?.error || t('purchaseQuotation.saveFailed'));
      }
      return null;
    } finally {
      setSaving(false);
    }
  };

  const handleApprove = async () => {
    if (!draftId || !canEdit) return;
    const hasMissingItem = lines.some((l) => !String(l.item_code || '').trim());
    if (hasMissingItem) {
      toast.error(
        t('purchaseQuotation.itemRequired') ||
        (lang === 'ar' ? 'يرجى اختيار رقم الصنف (Item No.) لجميع السطور للمتابعة.' : 'Please select an Item No. for all lines to proceed.')
      );
      return;
    }
    setApproving(true);
    setErrors({});
    try {
      const saved = await handleSave(true);
      if (!saved) return;
      const approved = await approvePurchaseQuotationDraftForPosting(draftId);
      setDraft(approved);
      const preview = await previewPurchaseQuotationPosting(draftId, true);
      setPostingPreview(preview);
      toast.success(t('purchaseQuotation.approvedForPosting'));
      goToStep(8);
    } catch (err) {
      console.error('Approval failed:', err);
      toast.error(err.response?.data?.error || t('purchaseQuotation.approvalFailed'));
    } finally {
      setApproving(false);
    }
  };

  const handlePreviewPayload = async () => {
    if (!draftId) return;
    setVerifyingPayload(true);
    try {
      await handleSave(true);
      const preview = await previewPurchaseQuotationPosting(draftId, true);
      setPostingPreview(preview);
      toast.info(lang === 'ar' ? 'تم تحديث معاينة بيانات المستند بنجاح' : 'Document data preview updated.');
    } catch (err) {
      console.error('Payload preview failed:', err);
      toast.error(err.response?.data?.error || t('purchaseQuotation.loadFailed'));
    } finally {
      setVerifyingPayload(false);
    }
  };

  const handlePostToSap = async () => {
    if (!draftId || draft?.status !== 'APPROVED_FOR_POSTING') return;
    setPosting(true);
    try {
      const result = await postPurchaseQuotationToSAP(draftId);
      if (result?.draft) {
        setDraft(result.draft);
        toast.success(t('purchaseQuotation.postSuccess'));
        navigate(`/shipping-delivery/documents/${draftId}`);
      }
    } catch (err) {
      console.error('SAP posting failed:', err);
      toast.error(err.response?.data?.error || t('purchaseQuotation.postFailed'));
      loadDraftData();
    } finally {
      setPosting(false);
    }
  };

  const handleCancel = async () => {
    if (!draftId || isPosted) return;
    if (!window.confirm(t('purchaseQuotation.confirmCancel'))) return;
    setCancelling(true);
    try {
      const cancelled = await cancelPurchaseQuotationDraft(draftId, 'Cancelled by user');
      setDraft(cancelled);
      toast.info(t('purchaseQuotation.cancelledSuccess'));
      navigate('/shipping-delivery');
    } catch (err) {
      console.error('Cancel failed:', err);
      toast.error(err.response?.data?.error || t('purchaseQuotation.cancelFailed'));
    } finally {
      setCancelling(false);
    }
  };

  // Render navigation buttons at the bottom of each step
  const renderWizardNav = (currentStepIdx) => (
    <div className="grpo-wizard-nav" style={{ marginTop: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
      <div>
        {currentStepIdx > 0 ? (
          <button
            type="button"
            className="app-button app-button--secondary"
            onClick={() => goToStep(currentStepIdx - 1)}
          >
            {lang === 'ar' ? '→ السابق' : '← Previous'}
          </button>
        ) : (
          <button
            type="button"
            className="app-button app-button--secondary"
            onClick={() => navigate('/shipping-delivery')}
          >
            {lang === 'ar' ? '→ القائمة' : '← Back to List'}
          </button>
        )}
      </div>

      <div style={{ display: 'flex', gap: '10px', alignItems: 'center', flexWrap: 'wrap' }}>
        {canEdit && (
          <button
            type="button"
            className="app-button app-button--secondary"
            onClick={() => handleSave(false)}
            disabled={saving || approving || posting}
          >
            {saving ? t('common.loading') : `💾 ${t('purchaseQuotation.saveDraft')}`}
          </button>
        )}

        {currentStepIdx < 8 ? (
          <button
            type="button"
            className="app-button app-button--primary"
            onClick={async () => {
              if (currentStepIdx === 0) {
                const trimmedVehicle = String(vehicleNumber || '').trim();
                if (trimmedVehicle.length > 11) {
                  toast.error(
                    t('purchaseQuotation.invalidVehicleNumber') ||
                    (lang === 'ar' ? 'رقم العربية لا يمكن أن يتجاوز 11 حرفاً.' : 'Vehicle number cannot exceed 11 characters.')
                  );
                  return;
                }
                const qtyNum = containerQuantity === '' ? 0 : Number(containerQuantity);
                if (isNaN(qtyNum) || !Number.isInteger(qtyNum) || qtyNum < 0) {
                  toast.error(
                    t('purchaseQuotation.invalidContainerQty') ||
                    (lang === 'ar' ? 'كمية الكونتينر يجب أن تكون رقماً صحيحاً غير سالب.' : 'Container quantity must be a whole non-negative number.')
                  );
                  return;
                }
                handleSave(true);
              }
              if (currentStepIdx === 1) {
                const effectiveVendor = getEffectiveVendorCode();
                if (!effectiveVendor) {
                  toast.error(t('purchaseQuotation.vendorRequired') || (lang === 'ar' ? 'يرجى اختيار مورد للمتابعة.' : 'Please select a vendor to proceed.'));
                  return;
                }
                handleSave(true);
              }
              if (currentStepIdx === 2) {
                const effectiveVendor = getEffectiveVendorCode();
                if (!effectiveVendor) {
                  toast.error(t('purchaseQuotation.vendorRequired') || (lang === 'ar' ? 'يرجى اختيار مورد للمتابعة.' : 'Please select a vendor to proceed.'));
                  return;
                }
                if (!postingDate || !validUntil || !documentDate || !requiredDate) {
                  toast.error(lang === 'ar' ? 'يرجى إدخال جميع التواريخ المطلوبة للمتابعة.' : 'Please enter all required dates to proceed.');
                  return;
                }
                if (postingDate && validUntil && validUntil < postingDate) {
                  toast.error(lang === 'ar' ? 'تاريخ الصلاحية لا يمكن أن يكون قبل تاريخ الترحيل.' : 'Valid until date cannot be before posting date.');
                  return;
                }
                handleSave(true);
              }
              if (currentStepIdx === 3) {
                const hasMissingGroup = lines.some((l) => !String(l.item_group_code || '').trim());
                if (hasMissingGroup) {
                  toast.error(
                    t('purchaseQuotation.itemGroupRequired') ||
                    (lang === 'ar' ? 'يرجى اختيار مجموعة الأصناف لجميع السطور للمتابعة.' : 'Please select an Item Group for all lines to proceed.')
                  );
                  return;
                }
                handleSave(true);
              }
              if (currentStepIdx === 4) {
                const hasMissingItem = lines.some((l) => !String(l.item_code || '').trim());
                if (hasMissingItem) {
                  toast.error(
                    t('purchaseQuotation.itemRequired') ||
                    (lang === 'ar' ? 'يرجى اختيار رقم الصنف (Item No.) لجميع السطور للمتابعة.' : 'Please select an Item No. for all lines to proceed.')
                  );
                  return;
                }
                handleSave(true);
              }
              if (currentStepIdx === 5) {
                const hasInvalidQty = lines.some((l) => Number(l.quoted_qty || 0) <= 0 || Number(l.required_qty || 0) <= 0);
                if (hasInvalidQty) {
                  toast.error(
                    t('purchaseQuotation.invalidQuantities') ||
                    (lang === 'ar' ? 'يرجى إدخال كميات صحيحة لجميع السطور للمتابعة.' : 'Please enter valid quantities for all lines to proceed.')
                  );
                  return;
                }
                handleSave(true);
              }
              if (currentStepIdx === 6) {
                handleSave(true);
              }
              if (currentStepIdx === 7) {
                handleSave(true);
              }
              goToStep(currentStepIdx + 1);
            }}
          >
            {lang === 'ar' ? 'التالي ←' : 'Next →'}
          </button>
        ) : null}

        {currentStepIdx === 8 && canAdministerQuotation && canEdit && draft?.status !== 'APPROVED_FOR_POSTING' && (
          <button
            type="button"
            className="app-button app-button--primary"
            onClick={handleApprove}
            disabled={approving || saving}
          >
            {approving ? (
              <>
                <CircularProgress size={16} color="inherit" />
                <span>{t('common.pleaseWait')}</span>
              </>
            ) : (
              <>✓ {t('purchaseQuotation.approveAndPreview')}</>
            )}
          </button>
        )}

        {currentStepIdx === 8 && canAdministerQuotation && draft?.status === 'APPROVED_FOR_POSTING' && (
          <button
            type="button"
            className="app-button app-button--primary"
            style={{ background: '#10b981', borderColor: '#10b981' }}
            onClick={handlePostToSap}
            disabled={posting}
          >
            {posting ? (
              <>
                <CircularProgress size={16} color="inherit" />
                <span>{t('purchaseQuotation.postingToSap')}</span>
              </>
            ) : (
              <>🚀 {t('purchaseQuotation.confirmPostToSap')}</>
            )}
          </button>
        )}
      </div>
    </div>
  );

  // Step 1: Vehicle & Container
  const renderVehicleStep = () => (
    <section className="card-panel quality-wizard-card--wide grpo-draft-card">
      <div className="quality-wizard-heading">
        <h1 className="page-title">{t('purchaseQuotation.steps.vehicle')}</h1>
        <p className="quality-wizard-subtitle">
          {t('purchaseQuotation.vehicleAndContainerDesc')}
        </p>
      </div>

      <div
        className="card-panel"
        style={{
          border: '1px solid var(--border)',
          borderRadius: '8px',
          padding: '16px',
          marginBottom: '20px',
          background: 'var(--color-bg-secondary, var(--color-bg))',
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '14px', flexWrap: 'wrap', gap: '8px' }}>
          <h3 style={{ margin: 0, fontSize: '1.05rem', fontWeight: 700 }}>
            🚛 {t('purchaseQuotation.vehicleAndContainer')}
          </h3>
        </div>

        <div className="quality-form-grid qrev-meta-grid">
          <label className="form-field">
            <span>{t('purchaseQuotation.vehicleNumber')}</span>
            <input
              className="app-input"
              type="text"
              maxLength={11}
              placeholder={t('purchaseQuotation.vehicleNumberPlaceholder')}
              value={vehicleNumber}
              disabled={!canEdit}
              onChange={(e) => setVehicleNumber(e.target.value)}
              onBlur={() => setVehicleNumber((prev) => prev.trim())}
            />
          </label>

          <label className="form-field">
            <span>{t('purchaseQuotation.containerQuantity')}</span>
            <input
              className="app-input"
              type="number"
              min="0"
              step="1"
              value={containerQuantity}
              disabled={!canEdit}
              onChange={(e) => {
                const val = e.target.value;
                if (val === '') {
                  setContainerQuantity('');
                  return;
                }
                if (/^\d+$/.test(val)) {
                  setContainerQuantity(val);
                }
              }}
              onKeyDown={(e) => {
                if (e.key === '.' || e.key === 'e' || e.key === 'E' || e.key === '+' || e.key === '-') {
                  e.preventDefault();
                }
              }}
              onBlur={() => {
                if (containerQuantity === '') {
                  setContainerQuantity('0');
                }
              }}
            />
          </label>
        </div>
      </div>

      {renderWizardNav(0)}
    </section>
  );

  // Step 2: Vendor Selection
  const renderVendorStep = () => (
    <section className="card-panel quality-wizard-card--wide grpo-draft-card">
      <div className="quality-wizard-heading">
        <h1 className="page-title">{t('purchaseQuotation.steps.vendor')}</h1>
        <p className="quality-wizard-subtitle">
          {t('purchaseQuotation.selectVendorPrompt')}
        </p>
      </div>

      <SearchableSelect options={[]} searchSource={farmSearch} disabled={!canEdit}
        value={getEffectiveVendorCode()} label={t('purchaseQuotation.vendor')}
        selectedOptions={[{ value: getEffectiveVendorCode(), label: `${getEffectiveVendorCode()} - ${getEffectiveVendorName()}` }]}
        onSearchResults={(rows) => setFarms(rows.map((row) => ({ ...row, code: row.farmCode, name: row.farmName })))}
        onSelectOption={(option) => {
          if (option?.raw) handleSelectVendor({ ...option.raw, code: option.raw.farmCode, name: option.raw.farmName });
          else { setVendorCardCode(''); vendorCardCodeRef.current = ''; setVendorName(''); vendorNameRef.current = ''; clearStoredVendor(draftId); }
        }} />

      {renderWizardNav(1)}
    </section>
  );

  // Step 3: Header & Dates
  const renderHeaderStep = () => (
    <section className="card-panel quality-wizard-card--wide grpo-draft-card">
      <div className="quality-wizard-heading">
        <h1 className="page-title">{t('purchaseQuotation.steps.header')}</h1>
        <p className="quality-wizard-subtitle">{t('purchaseQuotation.desc')}</p>
      </div>

      <div className="quality-form-grid qrev-meta-grid">
        {/* Posting Date */}
        <label className="form-field">
          <span>{t('purchaseQuotation.postingDate')} *</span>
          <input
            className="app-input"
            type="date"
            value={postingDate}
            disabled={!canEdit}
            onChange={(e) => setPostingDate(e.target.value)}
          />
        </label>

        {/* Valid Until */}
        <label className="form-field">
          <span>{t('purchaseQuotation.validUntil')} *</span>
          <input
            className="app-input"
            type="date"
            value={validUntil}
            disabled={!canEdit}
            onChange={(e) => setValidUntil(e.target.value)}
          />
        </label>

        {/* Document Date */}
        <label className="form-field">
          <span>{t('purchaseQuotation.documentDate')}</span>
          <input
            className="app-input"
            type="date"
            value={documentDate}
            disabled={!canEdit}
            onChange={(e) => setDocumentDate(e.target.value)}
          />
        </label>

        {/* Required Date */}
        <label className="form-field">
          <span>{t('purchaseQuotation.requiredDate')}</span>
          <input
            className="app-input"
            type="date"
            value={requiredDate}
            disabled={!canEdit}
            onChange={(e) => setRequiredDate(e.target.value)}
          />
        </label>

        {/* Vendor Ref No */}
        <label className="form-field">
          <span>{t('purchaseQuotation.vendorRefNo')}</span>
          <input
            className="app-input"
            type="text"
            value={vendorRefNo}
            disabled={!canEdit}
            onChange={(e) => setVendorRefNo(e.target.value)}
          />
        </label>

        {/* Group No */}
        <label className="form-field">
          <span>{t('purchaseQuotation.groupNo')}</span>
          <input
            className="app-input"
            type="text"
            value={groupNo}
            disabled={!canEdit}
            onChange={(e) => setGroupNo(e.target.value)}
          />
        </label>
      </div>

      {renderWizardNav(2)}
    </section>
  );

  // Step 4: Item Group
  const renderItemGroupStep = () => (
    <section className="card-panel quality-wizard-card--wide grpo-draft-card">
      <div className="quality-wizard-heading" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '12px' }}>
        <div>
          <h1 className="page-title">{t('purchaseQuotation.steps.itemGroup')}</h1>
          <p className="quality-wizard-subtitle">
            {t('purchaseQuotation.itemGroupStepDesc') || (lang === 'ar'
              ? 'اختر مجموعة الأصناف لكل سطر لتحميل الأصناف المطابقة.'
              : 'Select an item group for each shipping line to load matching items.')}
          </p>
        </div>
        {canEdit && (
          <button
            type="button"
            className="app-button app-button--secondary app-button--compact"
            onClick={handleAddLine}
          >
            ➕ {t('purchaseQuotation.addLine')}
          </button>
        )}
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginTop: '16px' }}>
        {lines.map((line, idx) => {
          const grpObj = itemGroups.find((g) => String(g.code) === String(line.item_group_code));
          const grpLabel = grpObj ? `${grpObj.code} - ${grpObj.name}` : line.item_group_code;

          return (
            <div
              key={idx}
              className="card-panel"
              style={{
                border: '1px solid var(--border)',
                borderRadius: '8px',
                padding: '16px',
                background: 'var(--color-bg-secondary, var(--color-bg))',
              }}
            >
              {/* Line Header */}
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  marginBottom: '14px',
                  paddingBottom: '8px',
                  borderBottom: '1px solid var(--border)',
                }}
              >
                <strong style={{ fontSize: '1rem', color: 'var(--color-primary)' }}>
                  #{idx + 1} {grpLabel ? `- ${grpLabel}` : (lang === 'ar' ? '- سطر جديد' : '- New Line')}
                </strong>
                {canEdit && lines.length > 1 && (
                  <button
                    type="button"
                    className="app-button app-button--danger app-button--compact"
                    style={{ fontSize: '0.8rem', padding: '4px 8px' }}
                    onClick={() => handleRemoveLine(idx)}
                  >
                    🗑️ {t('purchaseQuotation.removeLine')}
                  </button>
                )}
              </div>

              {/* Item Group Selector */}
              <div className="pq-item-stage">
                <div className="pq-item-stage__header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <h3 className="pq-item-stage__title">
                    {t('purchaseQuotation.sectionItemGroup')}
                  </h3>
                  {loadingItemGroups && (
                    <span style={{ display: 'inline-flex', alignItems: 'center', gap: '6px', fontSize: '0.82rem', color: 'var(--color-primary)' }}>
                      <CircularProgress size={14} color="inherit" />
                      {lang === 'ar' ? 'جاري تحميل المجموعات...' : 'Loading groups...'}
                    </span>
                  )}
                </div>
                <label className="form-field" style={{ margin: 0 }}>
                  <SearchableSelect
                    className="app-select"
                    disabled={!canEdit || loadingItemGroups}
                    loading={loadingItemGroups}
                    value={line.item_group_code || ''}
                    placeholder={loadingItemGroups ? (lang === 'ar' ? 'جاري تحميل المجموعات...' : 'Loading groups...') : `-- ${t('purchaseQuotation.selectItemGroup')} --`}
                    onChange={(e) => {
                      const grp = e.target.value;
                      handleLineChange(idx, 'item_group_code', grp);
                      handleLineChange(idx, 'item_code', '');
                      handleLineChange(idx, 'item_description', '');
                      handleLineChange(idx, 'uom_code', 'PCS');
                      setItemSearchMap((prev) => ({ ...prev, [idx]: '' }));
                    }}
                  >
                    <option value="">-- {t('purchaseQuotation.selectItemGroup')} --</option>
                    {itemGroups.map((g) => (
                      <option key={g.code} value={g.code}>
                        {g.code} - {g.name}
                      </option>
                    ))}
                  </SearchableSelect>
                </label>
              </div>
            </div>
          );
        })}
      </div>

      {renderWizardNav(3)}
    </section>
  );

  // Step 5: Item
  const renderItemStep = () => (
    <section className="card-panel quality-wizard-card--wide grpo-draft-card">
      <div className="quality-wizard-heading">
        <h1 className="page-title">{t('purchaseQuotation.steps.item')}</h1>
        <p className="quality-wizard-subtitle">
          {t('purchaseQuotation.itemStepDesc') || (lang === 'ar'
            ? 'اختر الصنف المطلوب لكل سطر من سطور مستند الشحن.'
            : 'Select the required item for each shipping document line.')}
        </p>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', marginTop: '16px' }}>
        {lines.map((line, idx) => {
          const currentGroupCode = line.item_group_code || '';

          const grpObj = itemGroups.find((g) => String(g.code) === String(currentGroupCode));
          const grpLabel = grpObj ? `${grpObj.code} - ${grpObj.name}` : currentGroupCode;

          return (
            <div
              key={idx}
              className="card-panel"
              style={{
                border: '1px solid var(--border)',
                borderRadius: '8px',
                padding: '16px',
                background: 'var(--color-bg-secondary, var(--color-bg))',
              }}
            >
              {/* Line Header */}
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  marginBottom: '14px',
                  paddingBottom: '8px',
                  borderBottom: '1px solid var(--border)',
                }}
              >
                <strong style={{ fontSize: '1rem', color: 'var(--color-primary)' }}>
                  #{idx + 1} - <span className="meta-label-icon" aria-hidden="true">{getProductIcon(line.item_description || line.item_code)}</span> {line.item_description || line.item_code || (lang === 'ar' ? 'اختيار الصنف' : 'Item Selection')}
                </strong>
                {grpLabel && (
                  <span style={{ fontSize: '0.82rem', color: 'var(--text-muted)' }}>
                    {t('purchaseQuotation.group')}: <strong>{grpLabel}</strong>
                  </span>
                )}
              </div>

