                  #{idx + 1} - <span className="meta-label-icon" aria-hidden="true">{getProductIcon(line.item_description || line.item_code)}</span> {line.item_description || line.item_code || (lang === 'ar' ? 'تفاصيل الصنف' : 'Item Details')}
